--------------------------------------------------------------------------------------Name:			160412[简体征服][活动脚本]6月老玩家回归活动礼包及发奖action--Purpose:		6月老玩家回归活动礼包及发奖action--Creator:		张世超--Created:		2016/06/01-------------------------------------------------------------------------------------- 40242 = V100\活动脚本\礼包函数\[征服][活动脚本]6月老玩家回归活动礼包及发奖action.lua-- 40242 = V100\ActiveScript\GiftPack\[Conquer][ActiveScript]WelcomeBackFJ.lua--前缀	WelcomeBackFJ_-- ##log 12000415 --常量表local tWelcomeBackFJ_Data = {}tWelcomeBackFJ_Data["Effect"] = "angelwing"tWelcomeBackFJ_Data["Pack"] = {}	--普通礼包奖励表tWelcomeBackFJ_Data["Pack"][3200460] = {}tWelcomeBackFJ_Data["Pack"][3200460][1] = 5000	--5000天石tWelcomeBackFJ_Data["Pack"][3200460][2] = 3200462	--外套可选包tWelcomeBackFJ_Data["Pack"][3200461] = {}tWelcomeBackFJ_Data["Pack"][3200461][1] = 3000	--3000天石tWelcomeBackFJ_Data["Pack"][3200461][2] = 3200462	--外套可选包tWelcomeBackFJ_Data["Garment"] = {}	--外套可选包tWelcomeBackFJ_Data["Garment"][3200462] = {}tWelcomeBackFJ_Data["Garment"][3200463] = {}tWelcomeBackFJ_Data["Garment"][3200464] = {}tWelcomeBackFJ_Data["Garment"][3200465] = {}tWelcomeBackFJ_Data["Garment"][3200462]["Option"] = {}tWelcomeBackFJ_Data["Garment"][3200463]["Option"] = {}tWelcomeBackFJ_Data["Garment"][3200464]["Option"] = {}tWelcomeBackFJ_Data["Garment"][3200465]["Option"] = {}tWelcomeBackFJ_Data["Garment"][3200462]["Attr"] = {}tWelcomeBackFJ_Data["Garment"][3200462]["Attr"].reduce_dmg = 1 --神佑tWelcomeBackFJ_Data["Garment"][3200462]["Option"][1] = 193295tWelcomeBackFJ_Data["Garment"][3200462]["Option"][2] = 193325tWelcomeBackFJ_Data["Garment"][3200462]["Option"][3] = 192785tWelcomeBackFJ_Data["Garment"][3200463]["Attr"] = ""tWelcomeBackFJ_Data["Garment"][3200463]["Option"][1] = 181345tWelcomeBackFJ_Data["Garment"][3200463]["Option"][2] = 181365tWelcomeBackFJ_Data["Garment"][3200463]["Option"][3] = 183305tWelcomeBackFJ_Data["Garment"][3200463]["Option"][4] = 181375tWelcomeBackFJ_Data["Garment"][3200463]["Option"][5] = 181925tWelcomeBackFJ_Data["Garment"][3200464]["Attr"] = ""tWelcomeBackFJ_Data["Garment"][3200464]["Option"][1] = 183325tWelcomeBackFJ_Data["Garment"][3200464]["Option"][2] = 181355tWelcomeBackFJ_Data["Garment"][3200464]["Option"][3] = 183315tWelcomeBackFJ_Data["Garment"][3200464]["Option"][4] = 183375tWelcomeBackFJ_Data["Garment"][3200464]["Option"][5] = 183335tWelcomeBackFJ_Data["Garment"][3200465]["Attr"] = ""tWelcomeBackFJ_Data["Garment"][3200465]["Option"][1] = 184365tWelcomeBackFJ_Data["Garment"][3200465]["Option"][2] = 187475tWelcomeBackFJ_Data["Garment"][3200465]["Option"][3] = 183485tWelcomeBackFJ_Data["Garment"][3200465]["Option"][4] = 188285tWelcomeBackFJ_Data["Garment"][3200465]["Option"][5] = 184355local tWelcomeBackFJ_Log = {}	tWelcomeBackFJ_Log["Pack"] = "0,0,%s,1,12000415,2,2[3200462],%s[1]"	--普通礼包	tWelcomeBackFJ_Log["Garment"] = "0,0,%s,1,12000415,2,%s,1"	--外套包--------------------------------------------------------------------------------------逻辑部分function WelcomeBackFJ_Pack(nItemId)	local nAddEmoney = tWelcomeBackFJ_Data["Pack"][nItemId][1]	local nAwardItem = tWelcomeBackFJ_Data["Pack"][nItemId][2]	if nAddEmoney+Get_UserEMoney() > G_User_MaxEmoney then		Sys_MsgBox(tWelcomeBackFJ_Text["Msg"]["CPLimit"])		return	end		if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then		local sALog = string.format(tWelcomeBackFJ_Log["Pack"],nItemId,nAddEmoney)		local sText = string.format(tWelcomeBackFJ_Text["Msg"]["Pack"],nAddEmoney)		User_AddEMoney(nAddEmoney)		Item_AddNewItem(nAwardItem,"")		Sys_SaveActionFestivalLog(sALog)		Sys_MsgBox(sText)		User_EffectAdd("self",tWelcomeBackFJ_Data["Effect"])	endend--外套可选包function WelcomeBackFJ_CoatSelect(nItemId)	local  sText = tWelcomeBackFJ_Text[nItemId] 	Sys_DialogText(sText)	for i,v in ipairs(tWelcomeBackFJ_Data["Garment"][nItemId]["Option"]) do		local sName = Get_ItemtypeName(v)		local sOptionText = sName.."."		local sFunc = "</F>WelcomeBackFJ_CoatComfirm</N>"..nItemId.."</N>"..v		Sys_DialogOption(sOptionText,sFunc)	end	Sys_DialogEnd()end--2次确认function WelcomeBackFJ_CoatComfirm(nItemId,nCoat)	local sName = Get_ItemtypeName(nCoat)	local sText =string.format(tWelcomeBackFJ_Text["Msg"]["Comfirm"],sName)	local sFunc1 = "</F>WelcomeBackFJ_CoatGet</N>"..nItemId.."</N>"..nCoat	local sFunc2 = "</F>WelcomeBackFJ_CoatSelect</N>"..nItemId	Sys_DialogText(sText)	Sys_DialogOption(tWelcomeBackFJ_Text["Msg"]["ComfirmOpt1"],sFunc1)	Sys_DialogOption(tWelcomeBackFJ_Text["Msg"]["ComfirmOpt2"],sFunc2)	Sys_DialogEnd()endfunction WelcomeBackFJ_CoatGet(nItemId,nCoat)	if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then		local sName = Get_ItemtypeName(nCoat)		local sText = string.format(tWelcomeBackFJ_Text["Msg"]["Garment"],sName)		local sLog =  string.format(tWelcomeBackFJ_Log["Garment"],nItemId,nCoat)		Item_AddNewItem(nCoat,tWelcomeBackFJ_Data["Garment"][nItemId]["Attr"])		Sys_SaveActionFestivalLog(sLog)		Sys_MsgBox(sText)		User_EffectAdd("self",tWelcomeBackFJ_Data["Effect"])			endend--------------------------------------物品配置-------------------------------------------tItem[3200460] = tItem[3200460] or {}tItem[3200460]["Function"] = function(nItemId,sItemName)	WelcomeBackFJ_Pack(nItemId)endtItem[3200461] = tItem[3200461] or {}tItem[3200461]["Function"] = function(nItemId,sItemName)	WelcomeBackFJ_Pack(nItemId)endtItem[3200462] = tItem[3200462] or {}tItem[3200462]["Function"] = function(nItemId,sItemName)	WelcomeBackFJ_CoatSelect(nItemId)endtItem[3200463] = tItem[3200463] or {}tItem[3200463]["Function"] = function(nItemId,sItemName)	WelcomeBackFJ_CoatSelect(nItemId)endtItem[3200464] = tItem[3200464] or {}tItem[3200464]["Function"] = function(nItemId,sItemName)	WelcomeBackFJ_CoatSelect(nItemId)endtItem[3200465] = tItem[3200465] or {}tItem[3200465]["Function"] = function(nItemId,sItemName)	WelcomeBackFJ_CoatSelect(nItemId)end